mapper.select:
Select b.*
From (select a.id,a.api_code,a.local_id,a.cust_num,a.extend03,
row_number() over(partition by cust_num order by extend03 asc) as rn
From b_sushang_transfer_data a
where local_id =#{local_id}
and (extend03 is not null and extend03 !='')
) b
Where b.rn = 1

    and b.id > #{indexId}

order by b.id asc limit #{pageSize};
